1	/** Flat fee added to every premium, regardless of the items insured. */
2	const PROCESSING_FEE = 5;
3	
4	/** Base premium of each insurable item type. */
5	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
6	  sword: 100,
7	  amulet: 60,
8	  staff: 80,
9	  potion: 40,
10	  rune: 25,
11	  moonstone: 25,
12	};
13	
14	/** Initial assessment surcharge on a customer's first insurance. */
15	const FIRST_INSURANCE_RATE = 0.1;
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Step = {
23	  op: string;
24	  items: Item[];
25	};
26	
27	export type Item = { type: string } & Record<string, unknown>;
28	
29	export type Result = { premium: number };
30	
31	export type ScenarioOutcome = { results: Result[] };
32	
33	/** A block is exactly this many items of one and the same type. */
34	const BLOCK_SIZE = 3;
35	
36	/** Special base premium charged for a complete block, instead of the per-item sum. */
37	const BLOCK_BASE_PREMIUM = 60;
38	
39	/** Number of items of each type on a policy. */
40	const countByType = (items: Item[]): Map<string, number> => {
41	  const counts = new Map<string, number>();
42	  for (const item of items) {
43	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
44	  }
45	  return counts;
46	};
47	
48	/** Base premium for all items of one and the same type. */
49	const groupBasePremium = (type: string, count: number): number =>
50	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUM_BY_TYPE[type];
51	
52	/** Base premium of a policy covering the given items. */
53	const calculateBasePremium = (items: Item[]): number =>
54	  [...countByType(items)].reduce(
55	    (total, [type, count]) => total + groupBasePremium(type, count),
56	    0,
57	  );
58	
59	/** Risk surcharge charged on the base premium of a cursed item. */
60	const CURSE_RATE = 0.5;
61	
62	/** Surcharges that attach to individual items rather than to the whole policy. */
63	const calculateItemSurcharges = (items: Item[]): number =>
64	  items.reduce(
65	    (sum, item) =>
66	      sum + (item.cursed ? BASE_PREMIUM_BY_TYPE[item.type] * CURSE_RATE : 0),
67	    0,
68	  );
69	
70	/** Premiums are rounded up — fractions of a gold piece fall to MHPCO. */
71	const roundPremiumUp = (amount: number): number => Math.ceil(amount);
72	
73	/** Price a policy covering the given items. */
74	const quotePremium = (items: Item[]): number => {
75	  const policyBasePremium = calculateBasePremium(items);
76	  const itemSurcharges = calculateItemSurcharges(items);
77	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
78	  return roundPremiumUp(
79	    policyBasePremium +
80	      itemSurcharges +
81	      firstInsuranceSurcharge +
82	      PROCESSING_FEE,
83	  );
84	};
85	
86	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
87	  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
88	});
